/*
 * valve.zip versioning service worker.
 *
 * The engine fetches a fixed, non-content-hashed URL (/valve.zip). nginx already
 * guards it with a content-based ETag (304 when the zip is unchanged, fresh 200
 * after a rebuild), but this worker adds a second, explicit content fingerprint
 * in the URL itself: /valve.zip?v=<sha256>. The version map comes from
 * /valve-versions.json, regenerated by start.sh / add-maps.sh from the zip's
 * actual bytes, so:
 *   - rebuilt zip  -> new ?v= -> different request URL -> no stale cache hit,
 *   - unchanged zip -> same ?v= -> same URL -> normal ETag revalidation/304.
 *
 * Everything except /valve.zip passes through untouched; in particular the
 * same-origin /websocket signaling upgrade is never intercepted (workers can't
 * touch WebSockets anyway) and /api/ state polling goes straight to the network.
 */
'use strict';

var VERSIONS_URL = '/valve-versions.json';
var ZIP_PATH = '/valve.zip';
var versions = {};

function stampVersion(url) {
    var v = versions['valve.zip'];
    if (!v) return url; // no manifest yet: let the ETag path handle caching
    var sep = url.indexOf('?') === -1 ? '?' : '&';
    // Don't double-stamp if the engine ever adds its own query string.
    if (url.indexOf('v=') !== -1) return url;
    return url + sep + 'v=' + encodeURIComponent(v);
}

self.addEventListener('install', function (event) {
    // Activate immediately so a freshly deployed worker versions at once.
    event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', function (event) {
    event.waitUntil(self.clients.claim());
});

self.addEventListener('message', function (event) {
    if (event.data && event.data.type === 'versions' && event.data.versions) {
        versions = event.data.versions;
    }
});

self.addEventListener('fetch', function (event) {
    var req = event.request;
    if (req.method !== 'GET') return;

    var url = new URL(req.url);
    if (url.origin !== self.location.origin) return;
    if (url.pathname !== ZIP_PATH) return;

    event.respondWith(
        // Refresh the version map (no-cache: the JSON itself is tiny and must
        // never lag a rebuild), then request the content-fingerprinted URL.
        fetch(VERSIONS_URL, { cache: 'no-store' })
            .then(function (r) { return r.json(); })
            .then(function (j) { versions = j || {}; })
            .catch(function () { /* keep the last known map / fall back bare */ })
            .then(function () {
                // Re-issue the SAME request (Range headers, credentials, mode…)
                // against the fingerprinted URL. Building a fresh Request from
                // the original preserves everything the engine's zip fetch set.
                var versioned = stampVersion(req.url);
                if (versioned === req.url) {
                    return fetch(req); // no manifest yet: ETag path handles it
                }
                return fetch(new Request(versioned, {
                    method: req.method,
                    headers: req.headers,
                    mode: req.mode,
                    credentials: req.credentials,
                    cache: req.cache,
                    redirect: req.redirect,
                    referrer: req.referrer,
                    referrerPolicy: req.referrerPolicy,
                    integrity: req.integrity
                }));
            })
    );
});
